cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Sum over dim=1
__global__ void row_sum_kernel(const float* input, float* output, int N, int C) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        float sum_val = 0.0f;
        for(int j = 0; j < C; j++){
            sum_val += input[i*C + j];
        }
        output[i] = sum_val;
    }
}

torch::Tensor row_sum_cuda(torch::Tensor input) {
    int N = input.size(0);
    int C = input.size(1);
    auto output = torch::empty({N, 1}, input.options());
    const int blockSize = 256;
    const int gridSize = (N + blockSize - 1) / blockSize;
    row_sum_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N,
        C
    );
    return output;
}

// Max over dim=1
__global__ void row_max_kernel(const float* input, float* output, int N, int C) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        float max_val = input[i*C];
        for(int j = 1; j < C; j++){
            float val = input[i*C + j];
            if(val > max_val) {
                max_val = val;
            }
        }
        output[i] = max_val;
    }
