# Build the extension
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_header,
    cuda_sources=cuda_source,
    functions=[
        "row_sum_cuda",
        "row_max_cuda",
        "row_mean_cuda",
        "row_logsumexp_cuda",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces several ops with custom CUDA kernels.
    Operations:
        1) Linear
        2) Sum over dim=1
        3) Max over dim=1
        4) Mean over dim=1
        5) LogSumExp over dim=1
        6) LogSumExp over dim=1
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.linear(x)
        x = self.custom_ops.row_sum_cuda(x)
        x = self.custom_ops.row_max_cuda(x)
        x = self.custom_ops.row_mean_cuda(x)
        x = self.custom_ops.row_logsumexp_cuda(x)
        x = self.custom_ops.row_logsumexp_cuda(x)
        return x

batch_size = 128
in_features = 10
out_features = 5

